const body = $json.body ?? {};
const job = body.job ?? body;

const clean = (value, max = 2500) =>
  String(value ?? "").trim().slice(0, max);

const list = (value, max = 30) =>
  Array.isArray(value)
    ? value.map((item) => clean(item, 500)).filter(Boolean).slice(0, max)
    : [];

const jobId = clean(body.jobId || job.id || job.jobId, 160);
if (!/^RES[0-9A-Za-z_-]+$/.test(jobId)) {
  throw new Error("Invalid or missing Merqiva research jobId");
}

const rawCallback = clean(body.callbackUrl || job.callbackUrl, 1000);
let callback;
try {
  callback = new URL(rawCallback);
} catch {
  throw new Error("Invalid callback URL");
}

const allowedHosts = new Set(["merqivaintel.com", "www.merqivaintel.com"]);
if (
  callback.protocol !== "https:" ||
  !allowedHosts.has(callback.hostname) ||
  callback.pathname !== "/api/research/callback"
) {
  throw new Error("Callback URL is not an approved Merqiva endpoint");
}

const productName = clean(job.productName, 240);
const researchQuestion = clean(job.researchQuestion, 2500);

if (!productName || !researchQuestion) {
  throw new Error("productName and researchQuestion are required");
}

return [{
  json: {
    jobId,
    callbackUrl: callback.toString(),
    productName,
    productId: clean(job.productId, 160),
    targetMarket: clean(job.targetMarket, 500),
    researchQuestion,
    targetCompanyTypes: list(job.targetCompanyTypes),
    targetVesselTypes: list(job.targetVesselTypes),
    relevantSignals: list(job.relevantSignals),
    targetDecisionMakerRoles: list(job.targetDecisionMakerRoles),
    maxOpportunities: Math.max(1, Math.min(10, Number(job.maxOpportunities) || 10)),
    language: ["en", "ar"].includes(job.language) ? job.language : "en"
  }
}];

const job = $node["Normalize Research Job"].json;
const response = $json;

function outputText(resp) {
  if (typeof resp?.output_text === "string" && resp.output_text.trim()) {
    return resp.output_text.trim();
  }

  const parts = [];
  for (const item of Array.isArray(resp?.output) ? resp.output : []) {
    if (item?.type !== "message") continue;
    for (const content of Array.isArray(item?.content) ? item.content : []) {
      if (content?.type === "output_text" && typeof content.text === "string") {
        parts.push(content.text);
      }
    }
  }
  return parts.join("\n").trim();
}

function normalizeUrl(value) {
  try {
    const url = new URL(String(value || "").trim());
    if (url.protocol !== "https:") return "";
    url.hash = "";
    return url.toString().replace(/\/$/, "");
  } catch {
    return "";
  }
}

const allowedUrls = new Set();

function collectUrlFields(value) {
  if (!value || typeof value !== "object") return;

  if (Array.isArray(value)) {
    for (const item of value) collectUrlFields(item);
    return;
  }

  for (const [key, item] of Object.entries(value)) {
    if (
      typeof item === "string" &&
      key.toLowerCase().includes("url")
    ) {
      const normalized = normalizeUrl(item);
      if (normalized) allowedUrls.add(normalized);
    } else if (item && typeof item === "object") {
      collectUrlFields(item);
    }
  }
}

for (const item of Array.isArray(response?.output) ? response.output : []) {
  if (item?.type === "web_search_call") {
    collectUrlFields(item);
  }

  if (item?.type === "message") {
    for (const content of Array.isArray(item?.content) ? item.content : []) {
      for (const annotation of Array.isArray(content?.annotations) ? content.annotations : []) {
        collectUrlFields(annotation);
      }
    }
  }
}

let raw = outputText(response)
  .replace(/^```json/i, "")
  .replace(/^```/i, "")
  .replace(/```$/i, "")
  .trim();

if (!raw) {
  throw new Error("OpenAI Responses API returned no output text");
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error("Research model did not return valid JSON: " + error.message);
}

const clamp = (value) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(100, Math.round(number)));
};

const clean = (value, max = 2500) =>
  String(value ?? "").trim().slice(0, max);

const signalList = (value) =>
  Array.isArray(value)
    ? value.map((item) => clean(
        typeof item === "string" ? item : item?.summary || item?.type || "",
        600
      )).filter(Boolean).slice(0, 20)
    : [];

const validated = [];
let rejectedForEvidence = 0;

for (const sourceOpportunity of Array.isArray(parsed?.opportunities) ? parsed.opportunities : []) {
  if (validated.length >= job.maxOpportunities) break;

  const companyName = clean(sourceOpportunity?.companyName, 240);
  if (!companyName) continue;

  const evidence = [];
  for (const item of Array.isArray(sourceOpportunity?.evidence) ? sourceOpportunity.evidence : []) {
    const sourceUrl = normalizeUrl(item?.sourceUrl);
    if (!sourceUrl || !allowedUrls.has(sourceUrl)) continue;

    const title = clean(item?.title, 240);
    const summary = clean(item?.summary, 1000);
    if (!title || !summary) continue;

    evidence.push({
      title,
      summary,
      sourceName: clean(item?.sourceName, 160),
      sourceUrl,
      observedAt: clean(item?.observedAt, 64),
      evidenceLevel: item?.evidenceLevel === "INFERENCE"
        ? "INFERENCE"
        : item?.evidenceLevel === "UNKNOWN"
          ? "UNKNOWN"
          : "VERIFIED FACT"
    });
  }

  const verifiedFacts = evidence.filter((item) => item.evidenceLevel === "VERIFIED FACT");
  if (!verifiedFacts.length) {
    rejectedForEvidence += 1;
    continue;
  }

  const dm = sourceOpportunity?.decisionMaker && typeof sourceOpportunity.decisionMaker === "object"
    ? sourceOpportunity.decisionMaker
    : {};

  let verificationEvidence = dm?.verificationEvidence && typeof dm.verificationEvidence === "object"
    ? {
        sourceName: clean(dm.verificationEvidence.sourceName, 200),
        sourceUrl: normalizeUrl(dm.verificationEvidence.sourceUrl),
        notes: clean(dm.verificationEvidence.notes, 1000),
        verifiedAt: clean(dm.verificationEvidence.verifiedAt, 64)
      }
    : null;

  if (
    verificationEvidence?.sourceUrl &&
    !allowedUrls.has(verificationEvidence.sourceUrl)
  ) {
    verificationEvidence = null;
  }

  let verificationStatus = clean(dm.verificationStatus, 20).toUpperCase();
  if (!["VERIFIED", "PARTIAL", "UNVERIFIED", "UNKNOWN"].includes(verificationStatus)) {
    verificationStatus = "UNKNOWN";
  }

  if (!verificationEvidence?.sourceUrl && verificationStatus === "VERIFIED") {
    verificationStatus = clean(dm.name, 200) ? "UNVERIFIED" : "UNKNOWN";
  }

  validated.push({
    companyName,
    productName: clean(sourceOpportunity?.productName || job.productName, 240),
    companyFit: clamp(sourceOpportunity?.companyFit),
    productFit: clamp(sourceOpportunity?.productFit),
    fleetFit: clamp(sourceOpportunity?.fleetFit),
    buyingSignalStrength: clamp(sourceOpportunity?.buyingSignalStrength),
    signalRecency: clamp(sourceOpportunity?.signalRecency),
    decisionMakerConfidence: clamp(sourceOpportunity?.decisionMakerConfidence ?? dm?.confidence),
    commercialRelevance: clamp(sourceOpportunity?.commercialRelevance),
    timingUrgency: clamp(sourceOpportunity?.timingUrgency),
    companyFitReason: clean(sourceOpportunity?.companyFitReason, 1200),
    productFitReason: clean(sourceOpportunity?.productFitReason, 1200),
    fleetFitReason: clean(sourceOpportunity?.fleetFitReason, 1200),
    whyNowSummary: clean(sourceOpportunity?.whyNowSummary || sourceOpportunity?.whyNow, 1800),
    buyingSignals: signalList(sourceOpportunity?.buyingSignals),
    decisionMaker: {
      name: clean(dm.name, 200),
      role: clean(dm.role || "UNKNOWN", 200) || "UNKNOWN",
      relevance: clamp(dm.relevance),
      influence: clamp(dm.influence),
      confidence: clamp(dm.confidence),
      verificationStatus,
      verificationEvidence
    },
    evidence: evidence.slice(0, 12),
    outreachDraft: clean(sourceOpportunity?.outreachDraft, 2000),
    status: "New"
  });
}

const notes = [
  clean(parsed?.notes, 1800),
  `Evidence gate kept ${validated.length} opportunity(s).`,
  rejectedForEvidence
    ? `${rejectedForEvidence} candidate(s) were rejected because no verified web-search source URL could be matched.`
    : "",
  allowedUrls.size
    ? `${allowedUrls.size} source URL(s) were available for validation.`
    : "No source URLs were available from the web-search response."
].filter(Boolean).join(" " );

return [{
  json: {
    jobId: job.jobId,
    callbackUrl: job.callbackUrl,
    provider: "N8N_OPENAI_WEB_SEARCH",
    status: "COMPLETED",
    notes: notes.slice(0, 2500),
    opportunities: validated
  }
}];
